fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    let mut it = txt.chars();

    let mut prev: Option<char> = None;
    let mut last: Option<char> = it.next();
    if last.is_none() {
        return false;
    }

    for c in it {
        prev = last;
        last = Some(c);
    }

    let last = last.unwrap();
    if !last.is_ascii_alphabetic() {
        return false;
    }

    match prev {
        None => true,          // exactly one character
        Some(' ') => true,     // preceded by a space
        Some(_) => false,
    }
}